            /// <summary>Rate</summary>
            [A(0)]
            long? Rate;
        }

        public class Mount {
            /// <summary>Container path.</summary>
            string? Target;

            /// <summary>
            /// Mount source (e.g. a volume name, a host path). The source cannot be
            /// specified when using `Type=tmpfs`. For `Type=bind`, the source path
            /// must either exist, or the `CreateMountpoint` must be set to `true` to
            /// create the source path on the host if missing.
            ///
            /// For `Type=npipe`, the pipe must exist prior to creating the container.
            /// </summary>
            string? Source;

            /// <summary>
            /// The mount type. Available types:
            ///
            /// - `bind` Mounts a file or directory from the host into the container. The `Source` must exist prior to
            /// creating the container.
            /// - `cluster` a Swarm cluster volume
            /// - `image` Mounts an image.
            /// - `npipe` Mounts a named pipe from the host into the container. The `Source` must exist prior to creating the
            /// container.
            /// - `tmpfs` Create a tmpfs with the given options. The mount `Source` cannot be specified for tmpfs.
            /// - `volume` Creates a volume with the given name and options (or uses a pre-existing volume with the same name
            /// and options). These are **not** removed when the container is removed.
            /// </summary>
            MountType? Type;

            /// <summary>Whether the mount should be read-only.</summary>
            bool? ReadOnly;

            /// <summary>The consistency requirement for the mount: `default`, `consistent`, `cached`, or `delegated`.</summary>
            string? Consistency;

            /// <summary>Optional configuration for the `bind` type.</summary>
            Mount.BindOptionS? BindOptions;

            /// <summary>Optional configuration for the `volume` type.</summary>
            Mount.VolumeOptionS? VolumeOptions;

            /// <summary>Optional configuration for the `image` type.</summary>
            Mount.ImageOptionS? ImageOptions;

            /// <summary>Optional configuration for the `tmpfs` type.</summary>
            Mount.TmpfsOptionS? TmpfsOptions;

            /// <summary>Optional configuration for the `bind` type.</summary>
            public class BindOptionS {
                /// <summary>A propagation mode with the value `[r]private`, `[r]shared`, or `[r]slave`.</summary>
                Mount.BindOptionS.PropagatioN? Propagation;

                /// <summary>Disable recursive bind mount.</summary>
                [Default(false)]
                bool? NonRecursive;

                /// <summary>Create mount point on host if missing</summary>
                [Default(false)]
                bool? CreateMountpoint;

                /// <summary>
                /// Make the mount non-recursively read-only, but still leave the mount recursive
                /// (unless NonRecursive is set to `true` in conjunction).
                ///
                /// Added in v1.44, before that version all read-only mounts were
                /// non-recursive by default. To match the previous behaviour this
                /// will default to `true` for clients on versions prior to v1.44.
                /// </summary>
                [Default(false)]
                bool? ReadOnlyNonRecursive;

                /// <summary>Raise an error if the mount cannot be made recursively read-only.</summary>
                [Default(false)]
                bool? ReadOnlyForceRecursive;

                public enum PropagatioN {
                    Private, // private
                    rprivate,
                    shared,
                    rshared,
                    slave,
                    rslave,
                }
            }

            /// <summary>Optional configuration for the `volume` type.</summary>
            public class VolumeOptionS {
                /// <summary>Populate volume with data from the target.</summary>
                [Default(false)]
                bool? NoCopy;

                /// <summary>User-defined key/value metadata.</summary>
                Map<string, string>? Labels;

                /// <summary>Map of driver specific options</summary>
                Mount.VolumeOptionS.DriverConfiG? DriverConfig;

                /// <summary>
                /// example: dir-inside-volume/subdirectory
                ///
                /// Source path inside the volume. Must be relative without any back traversals.
                /// </summary>
                string? Subpath;

                /// <summary>Map of driver specific options</summary>
                public class DriverConfiG {
                    /// <summary>Name of the driver to use to create the volume.</summary>
                    string? Name;

                    /// <summary>key/value map of driver specific options.</summary>
                    Map<string, string>? Options;
                }
            }

            /// <summary>Optional configuration for the `image` type.</summary>
            public class ImageOptionS {
                /// <summary>
                /// example: dir-inside-image/subdirectory
                ///
                /// Source path inside the image. Must be relative without any back traversals.
                /// </summary>
                string? Subpath;
            }

            /// <summary>Optional configuration for the `tmpfs` type.</summary>
            public class TmpfsOptionS {
                /// <summary>The size for the tmpfs mount in bytes.</summary>
                long? SizeBytes;

                /// <summary>
                /// The permission mode for the tmpfs mount in an integer.
                /// The value must not be in octal format (e.g. 755) but rather
                /// the decimal representation of the octal value (e.g. 493).
                /// </summary>
                int? Mode;

                /// <summary>
                /// example: [["noexec"]]
                ///
                /// The options to be passed to the tmpfs mount. An array of arrays.
                /// Flag options should be provided as 1-length arrays. Other types
                /// should be provided as as 2-length arrays, where the first item is
                /// the key and the second the value.
                /// </summary>
                string[,,][,,]? Options;
            }
        }

        /// <summary>
        /// The behavior to apply when the container exits. The default is not to
        /// restart.
        ///
        /// An ever increasing delay (double the previous delay, starting at 100ms) is
        /// added before each restart to prevent flooding the server.
        /// </summary>
        public class RestartPolicy {
            /// <summary>
            /// - Empty string means not to restart
            /// - `no` Do not automatically restart
            /// - `always` Always restart
            /// - `unless-stopped` Restart always except when the user has manually stopped the container
            /// - `on-failure` Restart only when the container exit code is non-zero
            /// </summary>
            RestartPolicy.NamE? Name;

            /// <summary>If `on-failure` is used, the number of times to retry before giving up.</summary>
            int? MaximumRetryCount;

            public enum NamE {
                unnamed,
                no,
                always,
                unless_stopped, // unless-stopped
                on_failure, // on-failure
            }
        }

