        public class PullIdentity {
            /// <summary>Repository is the remote repository location the image was pulled from.</summary>
            string? Repository;
        }

        /// <summary>SignatureIdentity contains the properties of verified signatures for the image.</summary>
        public class SignatureIdentity {
            /// <summary>Name is a textual description summarizing the type of signature.</summary>
            string? Name;

            /// <summary>Timestamps contains a list of verified signed timestamps for the signature.</summary>
            SignatureTimestamp[,,]? Timestamps;

            public const string KnownSigner = @"DHI";

            /// <summary>
            /// DockerReference is the Docker image reference associated with the signature.
            /// This is an optional field only present in older hashedrecord signatures.
            /// </summary>
            string? DockerReference;
            SignerIdentity? Signer;
            SignatureType? SignatureType;

            /// <summary>
            /// Error contains error information if signature verification failed.
            /// Other fields will be empty in this case.
            /// </summary>
            string? Error;

            /// <summary>
            /// Warnings contains any warnings that occurred during signature verification.
            /// For example, if there was no internet connectivity and cached trust roots were used.
            /// Warning does not indicate a failed verification but may point to configuration issues.
            /// </summary>
            string[,,]? Warnings;
        }

        /// <summary>SignatureTimestamp contains information about a verified signed timestamp for an image signature.</summary>
        public class SignatureTimestamp {
            SignatureTimestampType? Type;
            string? URI;
            DateTime? Timestamp;
        }

        /// <summary>SignerIdentity contains information about the signer certificate used to sign the image.</summary>
        public class SignerIdentity {
            /// <summary>CertificateIssuer is the certificate issuer.</summary>
            string? CertificateIssuer;

            /// <summary>SubjectAlternativeName is the certificate subject alternative name.</summary>
            string? SubjectAlternativeName;

            /// <summary>
            /// The OIDC issuer. Should match `iss` claim of ID token or, in the case of
            /// a federated login like Dex it should match the issuer URL of the
            /// upstream issuer. The issuer is not set the extensions are invalid and
            /// will fail to render.
            /// </summary>
            string? Issuer;

            /// <summary>Reference to specific build instructions that are responsible for signing.</summary>
            string? BuildSignerURI;

            /// <summary>Immutable reference to the specific version of the build instructions that is responsible for signing.</summary>
            string? BuildSignerDigest;

            /// <summary>
            /// Specifies whether the build took place in platform-hosted cloud infrastructure or customer/self-hosted
            /// infrastructure.
            /// </summary>
            string? RunnerEnvironment;

            /// <summary>Source repository URL that the build was based on.</summary>
            string? SourceRepositoryURI;

            /// <summary>Immutable reference to a specific version of the source code that the build was based upon.</summary>
            string? SourceRepositoryDigest;

            /// <summary>Source Repository Ref that the build run was based upon.</summary>
            string? SourceRepositoryRef;

            /// <summary>Immutable identifier for the source repository the workflow was based upon.</summary>
            string? SourceRepositoryIdentifier;

            /// <summary>Source repository owner URL of the owner of the source repository that the build was based on.</summary>
            string? SourceRepositoryOwnerURI;

            /// <summary>Immutable identifier for the owner of the source repository that the workflow was based upon.</summary>
            string? SourceRepositoryOwnerIdentifier;

            /// <summary>Build Config URL to the top-level/initiating build instructions.</summary>
            string? BuildConfigURI;

            /// <summary>Immutable reference to the specific version of the top-level/initiating build instructions.</summary>
            string? BuildConfigDigest;

            /// <summary>Event or action that initiated the build.</summary>
            string? BuildTrigger;

            /// <summary>Run Invocation URL to uniquely identify the build execution.</summary>
            string? RunInvocationURI;

            /// <summary>Source repository visibility at the time of signing the certificate.</summary>
            string? SourceRepositoryVisibilityAtSigning;
        }

        [Extension(@"x-go-name", @"Summary")]
        public class ImageSummary {
            /// <summary>
            /// example: sha256:ec3f0931a6e6b6855d76b2d7b0be30e81860baccd891b2e243280bf1cd8ad710
            ///
