        /// </summary>
        [Extension(@"x-go-name", @"Descriptor")]
        public class OCIDescriptor {
            /// <summary>
            /// example: application/vnd.oci.image.manifest.v1+json
            ///
            /// The media type of the object this schema refers to.
            /// </summary>
            string? mediaType;

            /// <summary>
            /// example: sha256:c0537ff6a5218ef531ece93d4984efc99bbf3f7497c0a7726c88e2bb7584dc96
            ///
            /// The digest of the targeted content.
            /// </summary>
            string? digest;

            /// <summary>
            /// example: 424
            ///
            /// The size in bytes of the blob.
            /// </summary>
            long? size;

            /// <summary>List of URLs from which this object MAY be downloaded.</summary>
            string[,,]? urls;

            /// <summary>
            /// example:
            /// {"com.docker.official-images.bashbrew.arch":"amd64","org.opencontainers.image.base.digest":"sha256:0d0ef5c914d3ea700147da1bd050c59edb8bb12ca312f3800b29d7c8087eabd8","org.opencontainers.image.base.name":"scratch","org.opencontainers.image.created":"2025-01-27T00:00:00Z","org.opencontainers.image.revision":"9fabb4bad5138435b01857e2fe9363e2dc5f6a79","org.opencontainers.image.source":"https://git.launchpad.net/cloud-images/+oci/ubuntu-base","org.opencontainers.image.url":"https://hub.docker.com/_/ubuntu","org.opencontainers.image.version":"24.04"}
            ///
            /// Arbitrary metadata relating to the targeted content.
            /// </summary>
            Map<string, string>? annotations;

            /// <summary>
            /// example: null
            ///
            /// Data is an embedding of the targeted content. This is encoded as a base64
            /// string when marshalled to JSON (automatically, by encoding/json). If
            /// present, Data can be used directly to avoid fetching the targeted content.
            /// </summary>
            string? data;
            OCIPlatform? platform;

            /// <summary>
            /// example: null
            ///
            /// ArtifactType is the IANA media type of this artifact.
            /// </summary>
            string? artifactType;
        }

