            string? ID;
            ObjectVersion? Version;

            [Format(@"dateTime")]
            string? CreatedAt;

            [Format(@"dateTime")]
            string? UpdatedAt;
            ClusterVolumeSpec? Spec;

            /// <summary>Information about the global status of the volume.</summary>
            ClusterVolume.InfO? Info;

            /// <summary>
            /// The status of the volume as it pertains to its publishing and use on
            /// specific nodes
            /// </summary>
            ClusterVolume.PublishStatuS[,,]? PublishStatus;

            /// <summary>Information about the global status of the volume.</summary>
            public class InfO {
                /// <summary>
                /// The capacity of the volume in bytes. A value of 0 indicates that
                /// the capacity is unknown.
                /// </summary>
                long? CapacityBytes;

                /// <summary>
                /// A map of strings to strings returned from the storage plugin when
                /// the volume is created.
                /// </summary>
                Map<string, string>? VolumeContext;

                /// <summary>
                /// The ID of the volume as returned by the CSI storage plugin. This
                /// is distinct from the volume's ID as provided by Docker. This ID
                /// is never used by the user when communicating with Docker to refer
                /// to this volume. If the ID is blank, then the Volume has not been
                /// successfully created in the plugin yet.
                /// </summary>
                string? VolumeID;

                /// <summary>The topology this volume is actually accessible from.</summary>
                Topology[,,]? AccessibleTopology;
            }

            public class PublishStatuS {
                /// <summary>The ID of the Swarm node the volume is published on.</summary>
                string? NodeID;

                /// <summary>
                /// The published state of the volume.
                /// * `pending-publish` The volume should be published to this node, but the call to the controller plugin to do
                /// so has not yet been successfully completed.
                /// * `published` The volume is published successfully to the node.
                /// * `pending-node-unpublish` The volume should be unpublished from the node, and the manager is awaiting
                /// confirmation from the worker that it has done so.
                /// * `pending-controller-unpublish` The volume is successfully unpublished from the node, but has not yet been
                /// successfully unpublished on the controller.
                /// </summary>
                ClusterVolume.PublishStatuS.StatE? State;

                /// <summary>
                /// A map of strings to strings returned by the CSI controller
                /// plugin when a volume is published.
                /// </summary>
                Map<string, string>? PublishContext;

                public enum StatE {
                    pending_publish, // pending-publish
                    published,
                    pending_node_unpublish, // pending-node-unpublish
                    pending_controller_unpublish, // pending-controller-unpublish
                }
            }
        }

        /// <summary>Cluster-specific options used to create the volume.</summary>
        public class ClusterVolumeSpec {
            /// <summary>
            /// Group defines the volume group of this volume. Volumes belonging to
            /// the same group can be referred to by group name when creating
            /// Services.  Referring to a volume by group instructs Swarm to treat
